def source_evidence(plan):
    for base, file_key, sha_key in ((DATA, 'design_file', 'design_sha256'), (DATA, 'algorithm_parent_evidence_file', 'algorithm_parent_evidence_sha256'),
        (ROOT, 'source_parent_identity_file', 'source_parent_identity_sha256'), (ROOT, 'source_parent_build_file', 'source_parent_build_sha256'),
        (DATA, 'clarification_file', 'clarification_sha256'), (DATA, 'previous_plan_file', 'previous_plan_sha256')):
        require(sha(base / plan[file_key]) == plan[sha_key], '测前设计、父、修订及声明修复身份')
    parent = read(ROOT / plan['source_parent_identity_file'])
    require(plan['source_count'] == len(plan['sources']) == 11, '十一份直接维护源')
    snapshots, parents = {}, {}
    for item in plan['sources']:
        name = item['canonical']; path = WORK / 'source' / name
        require(sha(path) == item['canonical_sha256'], '编译快照与计划一致：' + name)
        snapshots[name] = sha(path)
        if not item.get('new_file'):
            origin = ROOT / item['source']
            require(sha(origin) == item['source_sha256'] and parent['protected'][str(origin)] == item['source_sha256'], '父101身份包含该来源')
            parents[name] = origin
    name = 'src/experimental/normal_cholesky.cpp'
    original = parents[name].read_text(encoding='utf-8'); expected = original
    for before, after in normal_changes():
        expected = change(expected, before, after)
    actual = (WORK / 'source' / name).read_text(encoding='utf-8')
    require(expected == actual, 'normal仅八处已声明数学/作用域字面增量')
    restored = actual
    for before, after in reversed(normal_changes()):
        restored = change(restored, after, before)
    require(restored == original, 'normal全部增量可逆恢复生产父')
    moved = 'inline thread_local bool emit_diagnostics = true;\n'
    for name in ('src/experimental/presolve_state.hpp', 'src/experimental/coupled_state.hpp'):
        expected = change(parents[name].read_text(encoding='utf-8'), '#pragma once\n', '#pragma once\n#include "diagnostic_state.hpp"\n')
        if name.endswith('/presolve_state.hpp'):
            expected = change(expected, moved, '')
        require(expected == (WORK / 'source' / name).read_text(encoding='utf-8'), '状态头仅显式include及同一TLS定义迁移')
    diagnostic = '''#pragma once

// 各实验状态头共享同一线程的诊断输出开关，不依赖包含顺序。
namespace solver_v100_presolve {
inline thread_local bool emit_diagnostics = true;
}
'''
    require((WORK / 'source/src/experimental/diagnostic_state.hpp').read_text(encoding='utf-8') == diagnostic, '新头保留原namespace/type/TLS/初值')
