    require(len(unchanged) == 6 and all(parents[name].read_bytes() == (WORK / 'source' / name).read_bytes() for name in unchanged), '原六份算法/standalone源逐字不变')
    old = parents['tests/experimental/ipm_self_test.cpp'].read_text(encoding='utf-8')
