def compile_command(original, source, role, template, normal=False):
    result = list(original); old_work = Path(template['executable']).parent
    for option, value in (('-c', source), ('-o', WORK / (role + '.obj')), ('-MF', WORK / (role + '.obj.d')), ('-MT', WORK / (role + '.obj'))):
        if option in result:
            result[result.index(option) + 1] = str(value)
    if normal:
        positions = [index for index, value in enumerate(result) if value.startswith('-I') and Path(value[2:]).resolve() == (ROOT / 'include').resolve()]
        require(len(positions) == 1, 'normal公共include唯一')
        result[positions[0]] = '-I' + str(WORK / 'frozen/include')
        result[1:1] = ['-I' + str(WORK / 'source/include'), '-I' + str(WORK / 'source/src/experimental')]
    else:
        key = '-I' + str(old_work)
        require(result.count(key) == 1, '实验include唯一')
        result[result.index(key)] = '-I' + str(WORK / 'source/include')
        key = '-I' + str(old_work / 'frozen/include')
        if key in result:
            result[result.index(key)] = '-I' + str(WORK / 'frozen/include')
            result.insert(1, '-I' + str(WORK / 'source/src/experimental'))
    return result


