def validator(plan):
    require(sha(DATA / 'v100-run.py') == RUNNER_SHA and sha(DATA / plan['protocol_file']) == plan['protocol_sha256'], '锁定纯验证函数及共同协议')
    spec = importlib.util.spec_from_file_location('v102_locked_validator', DATA / 'v100-run.py')
    module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
    frozen = read(DATA / plan['protocol_file'])
    for key in ('sets', 'time_limit', 'wall_timeout', 'threads', 'seed', 'max_iterations', 'scaling_passes', 'shared_ipm', 'method', 'candidate_accuracy',
        'candidate_linear_solver', 'candidate_objective_scaling', 'candidate_backend_version', 'reference_accuracy', 'reference_linear_solver',
