        require(equal(plan[key], frozen[key]), '共同协议未变：' + key)
    return module, frozen


def stage_evidence(stage, plan, identity, runner, frozen):
    directory = RUNS / stage; manifest, stored = read(directory / 'manifest.json'), read(directory / 'summary.json')
    selected = runner.specification(stage, frozen); models, repeats, variants = selected['models'], selected['repeats'], runner.variants(stage)
    require(manifest['stage'] == stage and manifest['plan_sha256'] == PLAN_SHA == sha(directory / 'provenance/plan.json') and manifest['work'] == str(WORK) and
        manifest['build_identity_sha256'] == sha(WORK / 'identity.json') and equal(manifest['models'], models) and manifest['repeats'] == repeats and
        manifest['variants'] == list(variants) and manifest['models_file_sha256'] == selected['models_file_sha256'] == sha(selected['models_file']), '阶段固定集合、次数、次序和来源')
    require(all(manifest[key] == frozen[key] for key in ('time_limit', 'wall_timeout', 'threads', 'seed')) and manifest['reference'] == str(ROOT / '.tools/solver-ipm-v66.exe') and
        manifest['reference_sha256'] == plan['production_sha256'] and manifest['candidate'] == identity['candidate'] and manifest['candidate_sha256'] == identity['candidate_sha256'], '同期参考和候选身份')
    verify(manifest['protected']); raw_path = directory / 'runs.jsonl.gz'
    with gzip.open(raw_path, 'rt', encoding='utf-8') as stream:
        rows = [parse(line) for line in stream]
    schedule = list(runner.compare_lp.schedule(models, repeats, variants))
    require(len(rows) == len(schedule) == manifest['runs'], '完整固定调度，禁止省略失败或未完成阶段')
    counters = {key: 0 for key in runner.COUPLED_COUNTS}
    for index, (row, (model, repeat, position, variant)) in enumerate(zip(rows, schedule)):
        candidate = variant == variants[1]; executable = identity['candidate'] if candidate else manifest['reference']; expected_sha = identity['candidate_sha256'] if candidate else manifest['reference_sha256']
        require((row['run_index'], row['model_index'], row['repetition'], row['position_in_pair'], row['requested_variant'], row['protocol_variant']) ==
            (index, model['model_index'], repeat, position, variant, variant) and row['seed'] == frozen['seed'], '逐条调度身份')
        require(row['command'][:3] == [executable, 'solve', model['input']] and runner.valid_command(row, variant, frozen), '实际完整命令')
        require(row['solver_sha256_before'] == row['solver_sha256_after'] == row['frozen_solver_sha256'] == expected_sha == sha(executable) and
            row['model_sha256'] == row['model_sha256_after'] == row['frozen_model_sha256'] == model['sha256'] == sha(model['input']), '实际程序与输入前后身份')
        require(row['presolve_environment'] == ({runner.ENVIRONMENT: '1'} if variant == 'diagnostic_on' else {}), '实际环境保持')
        require(all(equal(row[key], value) for key, value in zip(MARKERS, runner.inspect_markers(row['stderr'], variant))), '三marker原件及partial/counters独立重解析')
        require(row['configuration_matches'] is runner.configuration_matches(row['report'], stage, variant, model, frozen), '完整配置重算')
        if row['report'] is not None:
            require(equal(parse(row['stdout']), row['report']), '公共报告来自实际stdout')
        require(all(equal(row[key], value) for key, value in runner.quality_fields(row, model, expected_sha, frozen).items()) and runner.valid_process(row), '原模型质量、工作账本、预算及罚分重算')
        if row['coupled_marker'] is not None:
            for key in counters:
                counters[key] += row['coupled_marker'][key]
    computed = runner.compare_lp.summarize(rows, models, repeats, frozen['wall_timeout'], frozen['time_limit'], variants)
    computed.update(schema=1, stage=stage, new_algorithm_round=True, plan_sha256=PLAN_SHA, raw_sha256=sha(raw_path), valid_process_count=sum(runner.valid_process(row) for row in rows),
        presolve_marker_error_count=sum(row['presolve_marker_error'] is not None for row in rows), coupled_marker_error_count=sum(row['coupled_marker_error'] is not None for row in rows),
        energy_marker_error_count=sum(row['energy_marker_error'] is not None for row in rows))
    require(equal(computed, stored), '实际summary全部字段与raw重算一致')
    return computed, rows, counters


def stages(plan, identity):
    runner, frozen = validator(plan); summaries, rows, counters = {}, {}, {}
    for stage in STAGES[:4]:
        summaries[stage], rows[stage], counters[stage] = stage_evidence(stage, plan, identity, runner, frozen)
    pairs = []
    for stage in STAGES[:2]:
        for model in runner.specification(stage, frozen)['models']:
            chosen = {row['requested_variant']: row for row in rows[stage] if row['model_index'] == model['model_index']}
            a, b = chosen['frozen_v66'], chosen['diagnostic_off']
            require(equal({key: value for key, value in a['report'].items() if key != 'timings'}, {key: value for key, value in b['report'].items() if key != 'timings'}), '关闭路径完整公共report仅排timings相等')
            pair = runner.pair_result(a, b, frozen); require(pair['category'] == 'equal', '固定17对子须非预算完整相等')
            pairs.append(dict(stage=stage, input=model['input'], **pair))
    require(len(pairs) == 17, '17关闭兼容对子')
    compatibility = dict(passed=True, plan_sha256=PLAN_SHA, runs=34, pairs=pairs, non_budget_equal=17, budget_pairs=0, invalid_pairs=0, different_pairs=0)
    require(equal(read(RUNS / 'compatibility.json'), compatibility), '兼容聚合重算')
    gate = runner.base.gate_decision(summaries['development'], summaries['probe']); gate['plan_sha256'] = PLAN_SHA
    gate['valid_processes'] = all(summaries[stage]['valid_process_count'] == summaries[stage]['run_count'] for stage in ('development', 'probe'))
    gate['eligible_for_netlib'] = gate['eligible_for_netlib'] and gate['valid_processes']
    require(equal(read(RUNS / 'gate.json'), gate), '冻结门槛由完整开发及探针重算')
    active = STAGES if gate['eligible_for_netlib'] else STAGES[:4]
    if gate['eligible_for_netlib']:
        for stage in STAGES[4:]:
            summaries[stage], rows[stage], counters[stage] = stage_evidence(stage, plan, identity, runner, frozen)
    else:
        require(not any((RUNS / stage).exists() for stage in STAGES[4:]), 'gatefalse不得扩集或忽略已跑阶段')
    total = sum(len(value) for value in rows.values()); require(total == (500 if gate['eligible_for_netlib'] else 136), '完整500或按计划条件停止136')
    goal = dict(achieved=False, evaluated=bool(gate['eligible_for_netlib']), status='progress', criterion='同期完整91例逐例覆盖不低于HiGHS且惩罚wallSGM10不高于HiGHS')
    if gate['eligible_for_netlib']:
        high = summaries['highs']; c, h = high['variants']['diagnostic_on'], high['variants']['highs']
        coverage = all(item['quality_pass_counts']['diagnostic_on'] >= item['quality_pass_counts']['highs'] for item in high['models'])
        achieved = coverage and c['penalized_wall_sgm10_seconds'] <= h['penalized_wall_sgm10_seconds']
        require(high['model_count'] == 91 and high['run_count'] == summaries['netlib']['run_count'] == 182, '同期完整91例两阶段')
        goal.update(achieved=achieved, status='complete' if achieved else 'progress', models=91, no_per_model_coverage_loss=coverage,
            candidate_coverage=c['all_repeats_quality_pass_model_count'], highs_coverage=h['all_repeats_quality_pass_model_count'],
            candidate_wall_sgm10_seconds=c['penalized_wall_sgm10_seconds'], highs_wall_sgm10_seconds=h['penalized_wall_sgm10_seconds'],
            candidate_numerical_sgm10_seconds=c['penalized_numerical_sgm10_seconds'], highs_numerical_sgm10_seconds=h['penalized_numerical_sgm10_seconds'],
            candidate_to_highs_wall_ratio=c['penalized_wall_sgm10_seconds'] / h['penalized_wall_sgm10_seconds'])
    return active, summaries, dict(public_lp_runs_revalidated=total, additional_public_lp_runs=0, compatibility_pairs=17, compatibility=compatibility,
        gate=gate, coupled_counter_totals=counters, goal=goal)


def attempts(plan, active):
    records = {}
    # attempt2计划/基线/静态证明也是JSON；只把含这两个标准键的原件解释为wrapper。
    for path in sorted(DATA.glob('v102-*-attempt*.json')):
        if any(path.name.startswith('v102-' + prefix) for prefix in ('closeout', 'outer', 'doc')):
            continue
        value = read(path)
        if not ('command' in value and 'input_sources_before_execution' in value):
            continue
        require(value['changed_inputs'] == [], '实际调用期间输入未变化')
        for name, item in value['input_sources_before_execution'].items():
            require(digest(item['source'].encode('utf-8')) == item['sha256'], '调用前源原文摘要：' + name)
        records[path.name] = dict(sha256=sha(path), command=value['command'], returncode=value['returncode'], elapsed_seconds=value['elapsed_seconds'])
    for label, numbers in (('build-self-check', (1, 2)), ('runner-self-check', (1, 2)), ('build', (1, 2))):
        for number in numbers:
            name = 'v102-' + label + '-attempt' + str(number) + '.json'
            require(name in records and records[name]['returncode'] == (1 if label == 'build' and number == 1 else 0), '失败首编译及两版真实自检完整保留')
    clarification = read(DATA / plan['clarification_file']); first = read(DATA / 'v102-build-attempt1.json')
    require(clarification['math_changed_by_correction'] is False and clarification['public_lp_runs_before_correction'] == 0 and
        clarification['failure_record_sha256'] == sha(DATA / 'v102-build-attempt1.json') and clarification['failed_normal_compile_sha256'] == sha(OLD_WORK / 'normal-compile.json'), '失败原件和声明依赖修复因果边界')
    failed = read(OLD_WORK / 'normal-compile.json'); old_plan = read(DATA / plan['previous_plan_file'])
    require(failed['returncode'] != 0 and not failed['wall_timeout'] and 'emit_diagnostics' in failed['stderr'] and old_plan['source_count'] == 10 and
        not (OLD_WORK / 'solver-experimental.exe').exists() and not (OLD_WORK / 'build-manifest.json').exists(), '首构建在normal编译失败，无可运行候选或公开LP')
    old_before = read(OLD_WORK / 'build-before.json')
    require(old_before['plan_sha256'] == plan['previous_plan_sha256'] and len(old_before['source_snapshot']) == 10, '首构建仍绑定原计划和十份快照')
    verify(old_before['source_snapshot'])
    for item in old_plan['sources']:
        require(sha(OLD_WORK / 'source' / item['canonical']) == item['canonical_sha256'], '首构建原十源不可改写')
    require((OLD_WORK / 'source/src/experimental/normal_cholesky.cpp').read_bytes() == (WORK / 'source/src/experimental/normal_cholesky.cpp').read_bytes(), '声明修复不改变normal数学源')
    for label in active:
        name = 'v102-' + label + '-attempt1.json'; require(name in records and records[name]['returncode'] == 0, '阶段真实唯一成功首尝试')
        require(len([key for key in records if key.startswith('v102-' + label + '-attempt')]) == 1, '阶段不得重跑替换')
    for label, directory in (('build-attempt1', OLD_WORK), ('build-attempt2', WORK), *((stage + '-attempt1', RUNS / stage) for stage in active)):
        raw = read(DATA / ('v102-' + label + '.json')); building = label.startswith('build-')
        script = ROOT / 'scripts' / ('build_experimental.py' if building else 'benchmark_experimental.py')
        copy = directory / 'provenance' / script.name
        captured = raw['input_sources_before_execution'][str(script)]
        require(raw['command'][1] == str(script) and captured['source'].encode('utf-8') == copy.read_bytes() and captured['sha256'] == sha(copy), '真实执行前源对应各自provenance，不替换历史工具')
    result = parse(read(DATA / 'v102-runner-self-check-attempt2.json')['stdout'])
    require(result['passed'] is True and result['public_lp_runs'] == 0 and result['maximum_solver_runs'] == 500, '正式修订计划纯运行器自检')
    return dict(wrappers=records, configuration_attempts_distinguished=True, failed_build_preserved=True, failed_build_public_lp_runs=0,
        first_build_elapsed_seconds=first['elapsed_seconds'], declaration_fix_only=True, original_plan_sha256=plan['previous_plan_sha256'])


def package(active):
    files = {PLAN, Path(__file__)}
    files.update(path for path in DATA.glob('v102-*.json') if not any(path.name.startswith('v102-' + prefix) for prefix in ('closeout', 'outer', 'doc')))
    files.update(ROOT / 'scripts' / name for name in ('build_experimental.py', 'benchmark_experimental.py', 'record_experiment.py', 'benchmark.py', 'compare_lp.py'))
    for directory in (OLD_WORK, WORK):
        files.update(path for path in directory.iterdir() if path.is_file() and path.suffix in ('.json', '.d'))
        files.update(path for path in (directory / 'source').rglob('*') if path.is_file())
        files.update(path for path in (directory / 'provenance').iterdir() if path.is_file())
    for stage in active:
        directory = RUNS / stage
        files.update(directory / name for name in ('manifest.json', 'summary.json', 'runs.jsonl.gz'))
        files.update(path for path in (directory / 'provenance').iterdir() if path.is_file())
    files.update(RUNS / name for name in ('compatibility.json', 'gate.json'))
    files.update(DATA / name for name in ('v100-run.py', 'v88-run.py', 'v66-run.py', 'v100-plan.json', 'ipm-v66-identity.json'))
    members = {}
    for path in sorted(files):
        path = path.resolve()
        require(path.is_file() and path.is_relative_to(ROOT) and path not in (OUTPUT, ARCHIVE) and path.suffix.lower() not in ('.exe', '.obj', '.o', '.a', '.lib') and
            not any(path.is_relative_to(directory / 'frozen') for directory in (OLD_WORK, WORK)), '归档只收本次只读源码和证据，排二进制及冻结重复')
        name = path.relative_to(ROOT).as_posix()
        require(name not in members and not PurePosixPath(name).is_absolute() and '..' not in PurePosixPath(name).parts, 'zip路径唯一且不越界')
        members[name] = dict(path=path, sha256=sha(path), size=path.stat().st_size)
    with zipfile.ZipFile(ARCHIVE, 'x', compression=zipfile.ZIP_DEFLATED) as archive:
        for name, item in members.items():
            archive.write(item['path'], name)
    with zipfile.ZipFile(ARCHIVE) as archive:
        require(len(archive.namelist()) == len(members) and set(archive.namelist()) == set(members), 'zip完整唯一成员')
        for name, item in members.items():
            raw = archive.read(name)
            require(digest(raw) == item['sha256'] == sha(item['path']) and len(raw) == item['size'], '逐成员SHA回读及原件一致')
    return dict(path=str(ARCHIVE), sha256=sha(ARCHIVE), members=len(members), bytes=ARCHIVE.stat().st_size, member_sha256={name: item['sha256'] for name, item in members.items()})


def main():
    require(not OUTPUT.exists() and not ARCHIVE.exists(), '结项JSON和zip必须独占新建')
    require(sha(PLAN) == PLAN_SHA, '正式修订计划身份')
    plan = read(PLAN)
    require(plan['candidate_version'] == 102 and plan['new_algorithm_round'] is True and plan['production_changes'] is False and plan['build_contract_revision'] == 2, '第99轮身份与声明修订边界')
    verify({str(ROOT / name): value for name, value in plan['tool_sources'].items()})
    baseline = read(DATA / 'v102-baseline-check-attempt2.json')
    require(baseline['passed'] is True and baseline['plan_sha256'] == PLAN_SHA, '修订后实际测前基线')
    source = source_evidence(plan); identity, build = build_evidence(plan)
    active, summaries, numerical = stages(plan, identity); history = attempts(plan, active); archive = package(active)
    result = dict(passed=True, created_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), version=102, round=99, new_algorithm_round=True,
        plan_sha256=PLAN_SHA, production_unchanged=True, source_generation=False, source_evidence=source, build_evidence=build, attempts=history,
        stages=list(active), stage_summaries=summaries, **numerical, archive=archive, driver_sha256=sha(__file__),
        interpretation='只在活动AAT完整成功因子内缓存LD逆对角，原矩阵/质量/额度保持。声明依赖修复单列，不删首编译失败；未达同期HiGHS目标则继续。')
    with OUTPUT.open('x', encoding='utf-8') as stream:
        json.dump(result, stream, ensure_ascii=False, indent=2, allow_nan=False); stream.write('\n')
    print(json.dumps({key: result[key] for key in ('passed', 'version', 'public_lp_runs_revalidated', 'additional_public_lp_runs', 'production_unchanged', 'goal')}, ensure_ascii=False))


if __name__ == '__main__':
    main()

